# Cas test_capacites du heros CARNAGE (Carnage / Eddie Brock, Neptune, prefixe `ca`) : noms commencant par le card_id
# (substituer_pack.py filtre dessus : `tools/substituer_pack.py <game_dir> <port> ca0`).
#
# Rappels de montage :
#  - ⚠ `Puzzle.EmptyEncounterDeck()` AVANT tout `Puzzle.Damage('01101', ..)` : le deck de Rhino porte d'autres exemplaires de 01101, et `Damage` en blesse UN QUELCONQUE
#    (constate le 03/11 : 2 degats poses, 0 lus sur le sbire en jeu) ;
#  - le deck `carnage_eddie_brock` demarre en ALTER EGO (ca001b) ; `Puzzle.ChangeToFace('ca001b', 'ca001a')` le passe en HEROS (Carnage) ;
#  - Rhino 01094 est le vilain (14 PV), 01097b son complot principal ; 01101 Hydra Mercenary (3 PV, Garde 1), 01102 Sandman (4 PV, Tenace) ;
#  - ressources : 01088 Energy = YY, 01089 Genius = BB, 01090 Strength = RR ;
#  - `Puzzle.EmptyHand()` AVANT un `Puzzle.Damage` en forme heros (sinon le pilote joue une interruption) ;
#  - `Puzzle.SendAfterRoundEnd()` envoie WhenRoundEnd puis AfterRoundEnd (fin de round).
HEROS = "Puzzle.ChangeToFace('ca001b', 'ca001a')"
VILAIN = '01094'
COMPLOT = '01097b'


def M(carte):
    return f"Puzzle.PutIntoPlay('{carte}', under_control=True)"


def DECK(*cartes):
    """Deck Rencontre dont la PREMIERE carte citee est le DESSUS (`CreateEncounterDeck` empile : la derniere creee est au-dessus)."""
    return ["Puzzle.EmptyEncounterDeck()", "Puzzle.CreateEncounterDeck(" + ", ".join(f"'{c}'" for c in reversed(cartes)) + ")"]


def _c(nom, pourquoi, mise, declencher, attendu, **cle):
    cas = {'nom': nom, 'pourquoi': pourquoi, 'scenario': cle.pop('scenario', 'rhino'), 'heros': cle.pop('heros', 'carnage_eddie_brock'),
           'mise_en_place': list(mise), 'declencher': list(declencher), 'verifier': cle.pop('verifier', 'etat_attendu'), 'attendu': attendu}
    cas.update(cle)
    return cas


